<script setup lang="ts">
import ServiceIntentList from '../components/ServiceIntentList.vue'
import {cloudApplications} from '../services/remoteApplications'
import {communityState,syncCommunity,cloudCommunity} from '../services/remoteCommunity'
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {store,toggleLike} from '../stores/community'
import {matchesPost,postKinds} from '../services/community'
const route=useRoute(),category=ref('all'),search=ref(''),following=ref(false),serviceRole=ref('find'),limit=ref(6),applicationsOpen=ref(false)
const intentTab=ref('mine')
const intentItems=computed(()=>store.applications.filter(a=>intentTab.value==='received'?a.received:!a.received))
const serviceZone=ref<HTMLElement|null>(null)
const categories=[{id:'all',label:'全部'},...postKinds.filter(k=>k.id!=='service'),{id:'service',label:'宠物服务'}]
const posts=computed(()=>store.posts.filter(p=>matchesPost(p,category.value,search.value)&&(!following.value||store.following.includes(p.ownerId||p.author))).sort((a,b)=>b.createdAt-a.createdAt))
const services=computed(()=>store.posts.filter(p=>p.kind==='service'&&p.serviceRole===(serviceRole.value==='find'?'offer':'find')&&matchesPost(p,'all',search.value)).sort((a,b)=>b.createdAt-a.createdAt))
watch([category,search,following],()=>limit.value=6)
watch(()=>route.query.section,value=>{if(value==='service')setTimeout(()=>serviceZone.value?.scrollIntoView({behavior:'smooth',block:'start'}),0)},{immediate:true})

</script>
<template><main class="community-page"><header class="community-top"><div><h1>社区</h1><p>找邻居搭把手，也分享养宠小日常</p></div><button aria-label="我的服务意向" @click="applicationsOpen=true"><van-icon name="records-o"/></button></header><van-search v-model="search" placeholder="搜索动态、服务、地区" shape="round" background="transparent"/>
<button v-if="cloudCommunity" class="load-more" :disabled="communityState.loading" @click="syncCommunity().catch(()=>{})">刷新云端动态</button><p v-if="communityState.loading" role="status">正在同步云端社区…</p><div v-if="communityState.error" role="alert">社区加载失败：{{communityState.error}} <button @click="syncCommunity().catch(()=>{})">重新加载</button></div><section class="community-entries"><article class="entry service-entry"><h2>宠物服务</h2><p>代遛、上门喂养、接送<br>找邻居搭把手</p><div><span>找服务</span><span>提供服务</span></div><button @click="serviceZone?.scrollIntoView({behavior:'smooth'})">进入服务区 ›</button></article><article class="entry post-entry"><h2>发布帖子</h2><p>约搭子、寻宠物、聊养宠<br>图文都可以</p><RouterLink to="/publish" class="entry-publish">发布帖子</RouterLink></article></section>
<section ref="serviceZone" class="community-panel service-zone"><div class="community-head"><h2>宠物服务互助</h2><RouterLink :to="{path:'/publish',query:{kind:'service',role:serviceRole}}">{{serviceRole==='find'?'发布需求':'发布服务'}} ›</RouterLink></div><div class="service-tabs" role="tablist" aria-label="服务方向"><button role="tab" :aria-selected="serviceRole==='find'" @click="serviceRole='find'">找服务</button><button role="tab" :aria-selected="serviceRole==='offer'" @click="serviceRole='offer'">提供服务</button></div><p class="community-note">{{serviceRole==='find'?'浏览服务者信息，提交咨询意向':'浏览邻居需求，表达接单意向'}} · {{cloudApplications?'云端意向':'仅本地演示'}}</p><div v-if="services.length" class="service-rows"><article v-for="s in services" :key="s.id" class="service-row"><img :src="s.avatar" :alt="s.author"/><RouterLink :to="'/posts/'+s.id" class="service-copy"><h3>{{s.title}}</h3><p>{{s.location||'地区待确认'}} · {{s.serviceKind||'宠物服务'}}</p><small>{{s.mine?'我的发布':s.sample?'示例用户':s.author}}</small></RouterLink><div class="service-side"><strong>{{s.price?'¥'+s.price:'待商议'}}</strong><RouterLink :to="'/posts/'+s.id">{{s.mine?'管理':serviceRole==='find'?'咨询':'我来接'}}</RouterLink></div></article></div><van-empty v-else description="没有匹配的服务信息"/><button class="application-link" @click="applicationsOpen=true">我的服务意向 · {{store.applications.filter(a=>!a.received&&a.status==='pending').length}} 条 ›</button></section>
<section class="community-feed"><div class="community-head"><h2>邻里动态</h2><RouterLink to="/publish">发布动态 ›</RouterLink></div><div class="discovery-tabs"><button :class="{selected:!following}" @click="following=false">发现</button><button :class="{selected:following}" @click="following=true">关注</button></div><div class="category-chips"><button v-for="c in categories" :key="c.id" :aria-pressed="category===c.id" @click="category=c.id">{{c.label}}</button></div><div class="community-waterfall" v-if="posts.length"><article v-for="p in posts.slice(0,limit)" :key="p.id" class="feed-card"><RouterLink :to="'/posts/'+p.id"><img v-if="p.image" class="feed-photo" :src="p.image" :alt="p.title" loading="lazy"/><div class="feed-copy"><div class="feed-tags"><span>{{p.category}}</span><span v-if="p.mine" class="mine-tag">我的发布</span><span v-else-if="p.sample">示例</span></div><h3>{{p.title}}</h3><p>{{p.content}}</p><small>{{p.location||'养宠生活'}}{{p.when?' · '+p.when:''}}</small></div></RouterLink><div class="feed-author"><img :src="p.avatar" alt=""/><span>{{p.author}}</span></div><div class="feed-actions"><button :class="{liked:p.liked}" :aria-label="p.liked?'取消点赞 '+p.title:'点赞 '+p.title" @click="toggleLike(p)"><van-icon :name="p.liked?'like':'like-o'"/> {{p.likes}}</button><RouterLink :to="'/posts/'+p.id"><van-icon name="chat-o"/> {{p.comments.length}}</RouterLink></div></article></div><van-empty v-else :description="following?'还没有关注的动态，去详情页关注喜欢的作者吧':'这个分类暂时没有动态'"><RouterLink to="/publish" class="entry-publish">发布第一条</RouterLink></van-empty><button v-if="posts.length>limit" class="load-more" @click="limit+=6">加载更多动态</button><p v-else-if="posts.length" class="community-end">已经看到最新动态啦 🐾</p></section><footer>{{cloudCommunity?'帖子、点赞、评论和关注已接入云端；服务意向也已同步云端，不构成预约或订单。':'服务信息与互动保存在当前浏览器，未向其他用户发送消息。'}}</footer>
<van-popup v-model:show="applicationsOpen" position="bottom" round closeable><div class="application-list"><h2>服务意向</h2><div class="service-tabs"><button :aria-selected="intentTab==='mine'" @click="intentTab='mine'">我提交的</button><button :aria-selected="intentTab==='received'" @click="intentTab='received'">我收到的</button></div><ServiceIntentList :items="intentItems" @navigate="applicationsOpen=false"/></div></van-popup></main></template>
