e-height:1.5;margin:8px 0 5px;overflow-wrap:anywhere}.feed-copy p{font-size:11px;line-height:1.65;color:#5a5070;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}.feed-copy>small{display:block;font-size:9px;color:#9a86a6;margin-top:7px;line-height:1.6}.feed-author{display:flex;align-items:center;gap:5px;padding:6px 10px;font-size:10px;color:#6b6086}.feed-author img{width:21px;height:21px;object-fit:cover;border-radius:50%}.feed-author span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.feed-actions{display:flex;align-items:center;justify-content:space-between;padding:6px 10px 12px;color:#8b7b99;font-size:11px}.feed-actions button{background:transparent;border:0;padding:0;color:inherit;font-size:11px}.feed-actions button.liked{color:#df7c81}.community-end,.community-page footer{font-size:11px;color:#9a86a6;text-align:center;line-height:1.7;margin-top:12px}.application-list{padding:28px 22px 40px}.application-list>p{font-size:11px;color:#8b7b99;margin:8px 0 20px}.application-list article{padding:15px;border-radius:18px;background:#f8f5fd;border:1px solid #e7ddf3;margin-bottom:12px}.application-list h3{font-size:14px}.application-list article p{font-size:11px;color:#6b6086;margin:7px 0}.application-list small{font-size:10px;color:#9a86a6}.application-list article>div{display:flex;gap:16px;margin-top:10px}.application-list article a,.application-list article button{font-size:12px;color:#2563eb;background:transparent;border:0;padding:0}
